class Solution
{
public:
    int shortestDistance(vector<vector<int>>& grid)
    {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> distance(m, vector<int>(n, 0));
        vector<vector<int>> reach(m, vector<int>(n, 0));
        const int dr[] = {1, -1, 0, 0};
        const int dc[] = {0, 0, 1, -1};
        int buildings = 0;
        for (int r = 0; r < m; ++r)
        {
            for (int c = 0; c < n; ++c)
            {
                if (grid[r][c] != 1) continue;
                ++buildings;
                queue<pair<int, int>> q;
                vector<vector<bool>> seen(m, vector<bool>(n, false));
                q.push({r, c});
                seen[r][c] = true;
                int steps = 0;
                while (!q.empty())
                {
                    int size = q.size();
                    ++steps;
                    while (size--)
                    {
                        auto cell = q.front();
                        q.pop();
                        for (int d = 0; d < 4; ++d)
                        {
                            int nr = cell.first + dr[d];
                            int nc = cell.second + dc[d];
                            if (nr < 0 || nr >= m || nc < 0 || nc >= n ||
                                seen[nr][nc] || grid[nr][nc] != 0) continue;
                            seen[nr][nc] = true;
                            distance[nr][nc] += steps;
                            ++reach[nr][nc];
                            q.push({nr, nc});
                        }
                    }
                }
            }
        }
        int best = INT_MAX;
        for (int r = 0; r < m; ++r)
        {
            for (int c = 0; c < n; ++c)
            {
                if (grid[r][c] == 0 && reach[r][c] == buildings)
                {
                    best = min(best, distance[r][c]);
                }
            }
        }
        return best == INT_MAX ? -1 : best;
    }
};
